public class RequestTimingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<RequestTimingMiddleware> _logger;

    public RequestTimingMiddleware(
        RequestDelegate next,
        ILogger<RequestTimingMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var start = Stopwatch.GetTimestamp();
        await _next(context);
        var elapsedMs = GetElapsedMilliseconds(start);

        _logger.LogInformation(
            "Request {Method} {Path} completed in {Elapsed}ms",
            context.Request.Method,
            context.Request.Path,
            elapsedMs);
    }

    private static double GetElapsedMilliseconds(long start)
    {
        var end = Stopwatch.GetTimestamp();
        var frequency = Stopwatch.Frequency;
        return (end - start) * 1000.0 / frequency;
    }
}

public class ActionExecutionListener : IObserver<KeyValuePair<string, object?>>
{
    private readonly ILogger<ActionExecutionListener> _logger;
    private Stopwatch? _sw;

    public ActionExecutionListener(
        ILogger<ActionExecutionListener> logger)
    {
        _logger = logger;
    }

    public void OnNext(KeyValuePair<string, object?> value)
    {
        if (value.Key == "Microsoft.AspNetCore.Mvc.BeforeActionExecution")
        {
            _sw = Stopwatch.StartNew();
        }
        else if (value.Key == "Microsoft.AspNetCore.Mvc.AfterActionExecution" && _sw is not null)
        {
            _sw.Stop();
            var evt = (value.Value as IDictionary<string, object?>)!;
            var action = evt["ActionDescriptor"]?.ToString() ?? "unknown";
            _logger.LogInformation(
                "Action {Action} took {Ms}ms",
                action,
                _sw.ElapsedMilliseconds);
        }
    }

    public void OnCompleted() { }
    public void OnError(Exception error) { }
}
